  orca: 'El Orca', casa: 'El Casa', memento: 'El Memento'
};

if (!adminState || !adminState.outlet_key) {
  await this.helpers.httpRequest({
    method: 'POST', url: `${BASE_URL}/sendMessage`,
    body: {
      chat_id: chatId,
      text: '⚠️ <b>Peringatan Admin:</b>\nFoto diterima, tetapi Anda belum memilih cabang!\n\nKetik <code>/updatebarcode</code> lalu pilih cabang terlebih dahulu.',
      parse_mode: 'HTML'
    },
    json: true
  });
} else {
  const outletName = OUTLET_NAMES[adminState.outlet_key] || adminState.outlet_key;
  await this.helpers.httpRequest({
    method: 'POST', url: `${BASE_URL}/sendMessage`,
    body: {
